//! Edit presets, converted by `edits preset to-rust` from Alight Motion projects (the project owner's anime edits;
//! community presets from github.com/andikachan/alight-web-editor, creators named in each preset) and Premiere Pro
//! transition presets on GitHub (wgetgoose/AdobePresets, Deep0902, felipoliver15-hash, Renderdragonorg,
//! asDJKLFHadjksh, ZenDev-arc). Timing, speed, camera moves, shakes, blurs and flashes only: no footage, no music.
#![allow(clippy::all)]
use crate::preset::{Curve, Ease, Ease::*, Flash, Motion, Preset, Slot};

fn c(k: &[(f64, f64, Ease)]) -> Curve {
    Curve { keys: k.to_vec() }
}

